/* eslint-disable no-unused-vars */
import React, { useEffect, useRef, useState } from 'react';
import './App.css';
import { Stages } from './Stages';

const Main = () => {
  
  const [selectedAnswer, setSelectedAnswer] = useState(null);
  const [radioSymbol, setRadioSymbol] = useState([]);
  const [questions, setQuestions] = useState([]);
  const [shuffledAnswers, setShuffledAnswers] = useState([]);
  const [stageCounter, setStageCounter] = useState(0);

  const videoRef = useRef(null);

  useEffect(() => {
    fetchQuestionsAndAnswers();
    if (videoRef.current) {
      const video = videoRef.current;
      var isPlaying = video.currentTime > 0 && !video.paused && !video.ended 
      && video.readyState > video.HAVE_CURRENT_DATA;
      if (!isPlaying) {
        video.play();
      }
      setTimeout(() => {
        video.classList.add('remove');
      }, 2000);
    }
  }, []);

  const fetchQuestionsAndAnswers = async () => {
    try {
      const response = await fetch('/home');
      const data = await response.json();
      setQuestions(data.questions);
      shuffleAnswers(data.questions[stageCounter]);
    } catch (error) {
      console.error('Error fetching data:', error);
    }
  };

  const shuffleAnswers = (questionData) => {
    if (questionData) {
      const { wrong, right } = questionData;
      const allAnswers = [...wrong, right];
  
      for (let i = allAnswers.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [allAnswers[i], allAnswers[j]] = [allAnswers[j], allAnswers[i]];
      }
  
      setShuffledAnswers(allAnswers);
      setRadioSymbol(Array(allAnswers.length).fill('◇'));
    }
  };

  const handleAnswerClick = (event, index) => {
    const selectedDiv = event.currentTarget;

    const answerDivs = document.querySelectorAll('.answer');
    answerDivs.forEach(div => {
      div.classList.remove('selected');
    });

    selectedDiv.classList.add('selected');

    const newRadioSymbols = Array(shuffledAnswers.length).fill('◇');
    newRadioSymbols[index] = '◈';
    setRadioSymbol(newRadioSymbols);

    const radioButton = selectedDiv.querySelector('input[type="radio"]');
    if (radioButton) {
      radioButton.checked = true;
      setSelectedAnswer(radioButton.id);
    }
  };

  const handleFormSubmit = (event) => {
    event.preventDefault();

    // Get the correct answer for the current stage
    const correctAnswer = questions[stageCounter].right;

    // Compare the selected answer with the correct answer
    if (selectedAnswer === correctAnswer) {
      // Update the UI for a correct answer
      const selectedDiv = document.querySelector('.selected');
      if (selectedDiv) {
        selectedDiv.classList.add('correct');
      }
    } else {
      // Update the UI for an incorrect answer
      const selectedDiv = document.querySelector('.selected');
      if (selectedDiv) {
        selectedDiv.classList.add('wrong');
      }
    }
  };

  return (
    <div className="bkgr" id="bkgr3">
      <video className="video" ref={videoRef} id="open_curt" autoPlay muted>
        <source src="/Img/open_curt.webm" type="video/webm" />
      </video>
      <Stages stagePass={stageCounter} />
      <form className="main_game" id="game_continue" onSubmit={handleFormSubmit}>
        <div className="question">{questions.length > 0 ? questions[stageCounter].question : ''}</div>
        <div className="answer_cont">
          <fieldset>
            {shuffledAnswers.map((answer, index) => (
              <div
                className={`answer ${radioSymbol[index] === '◈' ? 'selected' : ''}`}
                key={`answer_${index}`}
                onClick={(event) => handleAnswerClick(event, index)}
              >
                <span className="answer_letter">{radioSymbol[index]}</span>
                <input type="radio" id={`Answer_${index}`} name="answers"></input>
                <label htmlFor={`Answer_${index}`}>{answer}</label>
              </div>
            ))}
          </fieldset>
        </div>
        <div className="line2"></div>
        <div className="option_cont">
          <div className="check_btn" >Quit game</div>
          <div className="help_cont">
            <div className="help" id="fifty"></div>
            <div className="help used" id="people"></div>
            <div className="help" id="refresh"></div>
          </div>
          <input type='submit' className="check_btn" value="Submit answer"></input>
        </div>
        <div className="line2"></div>
      </form>
    </div>
  );
}

export default Main
